// Proposal A proposal for resolving a conflict the client asserts, carried on a
// `contradicts` relationship (HCP 4.7.4). It changes nothing until the Context Subject
// acts. `proposedBy` and `proposedAt` are set by the provider, never taken from a request
// (HCP 4.7.4).
type Proposal struct {
	// The act proposed (HCP 4.7.3).
	Act ProposalAct `json:"act"`

	// The entry the act applies to: its `ref` for a Context Client, its `id` for a Management
	// Client (HCP 5.2.3).
	Entry string `json:"entry"`

	// Why, in words the Context Subject can read (HCP 4.7.4).
	Rationale string `json:"rationale"`

	// What the proposal considered: an open set, of which HCP defines `basis`,
	// `declarationType`, `standing`, `permittedPurposes`, `recency` and `confidence` (HCP
	// 4.7.4).
	Weighed []string `json:"weighed"`
}

// WriteProvenance HCP `record.provenance`, as a revision supplies it (HCP 5.2.4): the
// members are as for create, for the revised assertion, and the provider assigns every
// other provenance member (HCP 3.5). The create rules for `source` and `assertedBy.id`
// apply to the revised assertion (HCP 5.2.3, 5.2.4); they depend on the content and are
// not checked by the schema.
type WriteProvenance struct {
	// The Context Asserter.
	AssertedBy *AssertedBy `json:"assertedBy,omitempty"`

	// When the assertion was made. Omitted means the provider records `recordedAt` (HCP
	// 5.2.3).
	AssertedAt *Instant `json:"assertedAt,omitempty"`

	// The origin of the entry: a conversation or document identifier, `person-input` or
	// `integration` (HCP 4.2, 5.2.3).
	Source *string `json:"source,omitempty"`
}

// AssertedBy HCP `record.provenance.assertedBy`, as a request supplies it: the Context
// Asserter's identifier only. The provider assigns `assurance` (HCP 3.5, 5.2.3).
type AssertedBy struct {
	// The Context Asserter (HCP 3.2.6).
	ID string `json:"id"`
}

// RevisionAssertionDeclarationType The declaration type of the revised assertion (HCP
// 4.4). HCP's own values, carried verbatim.
type RevisionAssertionDeclarationType string

// Values RevisionAssertionDeclarationType may take, per this specification's schema.
const (
	RevisionAssertionDeclarationTypePersonDeclared RevisionAssertionDeclarationType = "person-declared"
	RevisionAssertionDeclarationTypeModelInferred  RevisionAssertionDeclarationType = "model-inferred"
	RevisionAssertionDeclarationTypeIssuerAttested RevisionAssertionDeclarationType = "issuer-attested"
)

// RevisionAssertion The assertion members a revision may supply (HCP 5.2.4).
// `declarationType` omitted means unchanged. `confidence` is REQUIRED and non-null when
// the revised declaration type is `model-inferred`, and null or absent otherwise (HCP
// 4.2, 5.2.3); not checked by the schema, since the registry's Rust generator does not
// support `if`/`then`/`else`.
type RevisionAssertion struct {
	// The declaration type of the revised assertion (HCP 4.4). HCP's own values, carried
	// verbatim.
	DeclarationType *RevisionAssertionDeclarationType `json:"declarationType,omitempty"`

	// As for create (HCP 5.2.3).
	Confidence *string `json:"confidence,omitempty"`

	// As for create: when the content stops holding (HCP 4.2).
	ValidUntil *string `json:"validUntil,omitempty"`

	// As for create: what the assertion was drawn from (HCP 4.2.5).
	Basis *Basis `json:"basis,omitempty"`

	// As for create: the purposes the asserter permits the entry to be used for (HCP 4.2.6).
	// The bound of 256 is a framework bound.
	PermittedPurposes *[]PurposeCode `json:"permittedPurposes,omitempty"`
}

// Payload The request payload of the HCP 2.0-draft-3 Revise operation (HCP 5.2.4): an HCP
// Client writes a new version of an entry, replacing its content, assertion and evidence
// whole, provided the version it names is still current. The outer document members (id,
// type, issuer, recipient, issuedAt, expiresAt, proof) are owned by the framework — SPEC
// §6.3.
type Payload struct {
	// HCP `ref`: the entry to revise, by the grant-scoped reference a Context Client was
	// given (HCP 5.2.4, 7.4). Exactly one of `ref` and `entryId` is present; not checked by
	// the schema, and a request with both or neither fails with `malformedRequest`.
	Ref *string `json:"ref,omitempty"`

	// HCP `entryId`: the entry to revise, by its `id`, as a Management Client names it (HCP
	// 5.2.4).
	EntryID *Urn `json:"entryId,omitempty"`

	// HCP `expectedVersion`: the `record.version` of the current version, which this revision
	// replaces. Where it is not the current version, the revision fails with
	// `hcp:versionConflict` and changes nothing (HCP 5.2.4).
	ExpectedVersion int64 `json:"expectedVersion"`

	// HCP `content`: the revised content, whole. Where the content is a credential, the new
	// credential is supplied whole in `evidence` (HCP 5.2.4).
	Content Content `json:"content"`

	// HCP `evidence`: the revision's evidence items, whole; absent means none (HCP 5.2.4). At
	// most one item has `role` `content` (HCP 4.2.2); not checked by the schema, since the
	// registry's Rust generator does not support `contains`. The bound of 64 is a framework
	// bound.
	Evidence *[]EvidenceItem `json:"evidence,omitempty"`

	// HCP `reason`: why the entry is revised, recorded in the audit log (HCP 5.2.4). The
	// maxLength is a framework bound, not an HCP requirement.
	Reason string `json:"reason"`

	// HCP `assertion.*`: the revised assertion; `declarationType` omitted means unchanged,
	// and the other members are as for create (HCP 5.2.4).
	Assertion *RevisionAssertion `json:"assertion,omitempty"`

	// HCP `record.provenance.*` for the revised assertion, and `record.relationships`, as for
	// create (HCP 5.2.4).
	Record *WriteRecord `json:"record,omitempty"`

	// The HCP access token that stands for the grant (HCP 12, 13), carried unchanged. HCP's
	// HTTP binding sends it as a Bearer token (HCP 9.3); this member carries it in the
	// document. The provider validates it exactly as over HTTP and treats it as opaque.
	AccessToken string `json:"accessToken"`
}

// TypeURI is the Trust Task type URI this package's Payload is carried under.
const TypeURI = "https://trusttasks.org/spec/hcp/entries/revise/0.1"

// Extends is the MAJOR.MINOR of this specification that this version declares it
// extends (SPEC §5.2 "Declared extension"), or "" when it declares none. A
// consumer implementing that version may read this version's documents by
// ignoring the payload members it does not recognise — see
// trusttasks.ReadForSpec. The direct declaration only; the chain is walked
// through the registry-wide index in package specs.
const Extends = ""

// Deprecation is empty for a current specification version, and otherwise says
// why this one is deprecated and what replaces it: "superseded by <slug>/<M.N>",
// "retired; use <slug>/<M.N>" or "retired". A deprecated version is still
// supported, but is withdrawn from this module in a later scheduled release.
const Deprecation = ""

// ResponseTypeURI is the success-response form of TypeURI (SPEC §4.4.1).
const ResponseTypeURI = "https://trusttasks.org/spec/hcp/entries/revise/0.1#response"

