const PayloadSchemaJSON = "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://trusttasks.org/spec/hcp/entries/revise/0.1\",\"title\":\"HCP — Revise Entry — payload\",\"description\":\"The request payload of the HCP 2.0-draft-3 Revise operation (HCP 5.2.4): an HCP Client writes a new version of an entry, replacing its content, assertion and evidence whole, provided the version it names is still current. The outer document members (id, type, issuer, recipient, issuedAt, expiresAt, proof) are owned by the framework — SPEC §6.3.\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"expectedVersion\",\"content\",\"reason\",\"accessToken\"],\"properties\":{\"ref\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"HCP `ref`: the entry to revise, by the grant-scoped reference a Context Client was given (HCP 5.2.4, 7.4). Exactly one of `ref` and `entryId` is present; not checked by the schema, and a request with both or neither fails with `malformedRequest`.\"},\"entryId\":{\"$ref\":\"#/$defs/Urn\",\"description\":\"HCP `entryId`: the entry to revise, by its `id`, as a Management Client names it (HCP 5.2.4).\"},\"expectedVersion\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"HCP `expectedVersion`: the `record.version` of the current version, which this revision replaces. Where it is not the current version, the revision fails with `hcp:versionConflict` and changes nothing (HCP 5.2.4).\"},\"content\":{\"$ref\":\"#/$defs/Content\",\"description\":\"HCP `content`: the revised content, whole. Where the content is a credential, the new credential is supplied whole in `evidence` (HCP 5.2.4).\"},\"evidence\":{\"type\":\"array\",\"maxItems\":64,\"items\":{\"$ref\":\"#/$defs/EvidenceItem\"},\"description\":\"HCP `evidence`: the revision's evidence items, whole; absent means none (HCP 5.2.4). At most one item has `role` `content` (HCP 4.2.2); not checked by the schema, since the registry's Rust generator does not support `contains`. The bound of 64 is a framework bound.\"},\"reason\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1024,\"description\":\"HCP `reason`: why the entry is revised, recorded in the audit log (HCP 5.2.4). The maxLength is a framework bound, not an HCP requirement.\"},\"assertion\":{\"$ref\":\"#/$defs/RevisionAssertion\",\"description\":\"HCP `assertion.*`: the revised assertion; `declarationType` omitted means unchanged, and the other members are as for create (HCP 5.2.4).\"},\"record\":{\"$ref\":\"#/$defs/WriteRecord\",\"description\":\"HCP `record.provenance.*` for the revised assertion, and `record.relationships`, as for create (HCP 5.2.4).\"},\"accessToken\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":8192,\"description\":\"The HCP access token that stands for the grant (HCP 12, 13), carried unchanged. HCP's HTTP binding sends it as a Bearer token (HCP 9.3); this member carries it in the document. The provider validates it exactly as over HTTP and treats it as opaque.\"}},\"$defs\":{\"Instant\":{\"type\":\"string\",\"format\":\"date-time\",\"description\":\"An RFC 3339 instant.\"},\"RelationshipType\":{\"type\":\"string\",\"enum\":[\"derivedFrom\",\"supersedes\",\"contradicts\",\"duplicates\"],\"description\":\"How one entry relates to another (HCP 4.2.3). HCP's own values, carried verbatim.\"},\"EvidenceItem\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"role\",\"type\"],\"description\":\"One evidence item (HCP 4.2.2). An item of a type the provider does not recognize is preserved and never raises assurance (HCP A.3). An item whose type is `verifiable-credential` MUST carry `credential`, an object with `@context`, `type`, `issuer` and `credentialSubject`, held whole as its issuer secured it (HCP 4.2.2). This rule is stated here and not as a schema conditional: the registry's Rust generator does not support `if`/`then`/`else`, so a validator does not check it.\",\"properties\":{\"role\":{\"type\":\"string\",\"enum\":[\"content\",\"supports\"],\"description\":\"`content`: the item's credential is the entry's content (VC Evidence profile). `supports`: the item backs content stated elsewhere in the entry (HCP 4.2.2).\"},\"type\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The evidence type: `verifiable-credential`, or a URI (HCP 4.2.2, A.3).\"},\"credential\":{\"description\":\"The credential: for `verifiable-credential`, a W3C Verifiable Credential with `@context`, `type`, `issuer` and `credentialSubject`, whose own data model governs its contents (HCP 4.2.2, 14.2).\"},\"verification\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"result\",\"at\"],\"description\":\"The provider's record of its most recent verification of the credential (HCP 4.2.2). Set only by the provider.\",\"properties\":{\"result\":{\"type\":\"string\",\"enum\":[\"verified\",\"failed\"],\"description\":\"The outcome.\"},\"at\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the provider verified.\"},\"by\":{\"type\":\"string\",\"enum\":[\"provider\",\"trust-domain\"],\"description\":\"Who verified: the provider, or the Context Subject's trust domain under end-to-end encrypted storage (HCP 4.8). HCP's own values, carried verbatim.\"}}}}},\"PurposeCode\":{\"type\":\"string\",\"format\":\"uri\",\"minLength\":1,\"maxLength\":2048,\"pattern\":\"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+$\",\"description\":\"An HCP purpose code: an absolute URI naming the purpose for which context is requested or may be used (HCP 6.1.5.2).\"},\"Basis\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"What an assertion was drawn from (HCP 4.2.5). It identifies no party but the Context Subject.\",\"properties\":{\"drawnFrom\":{\"type\":\"array\",\"maxItems\":256,\"items\":{\"type\":\"string\",\"maxLength\":2048},\"description\":\"The sources the assertion was drawn from. The bound of 256 is a framework bound, not an HCP requirement.\"},\"task\":{\"type\":\"string\",\"maxLength\":4096,\"description\":\"The task during which the assertion was made.\"},\"setting\":{\"type\":\"string\",\"maxLength\":4096,\"description\":\"The setting in which the assertion was made.\"},\"rationale\":{\"type\":\"string\",\"maxLength\":4096,\"description\":\"Why the asserter drew the conclusion.\"}}},\"Content\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"profile\"],\"description\":\"Entry content. `profile` names its shape (HCP 4.2). Under the General Context profile it carries `value` and optionally `language` (HCP 11.2); under the VC Evidence profile it carries `evidence`, the index of the evidence item holding the credential, and no `value` (HCP 4.2.2, 14). So `value` is REQUIRED under General Context, and under VC Evidence `evidence` is REQUIRED and `value` is forbidden. This rule is stated here and not as a schema conditional: the registry's Rust generator does not support `if`/`then`/`else`, so a validator does not check it.\",\"properties\":{\"profile\":{\"$ref\":\"#/$defs/Uri\",\"description\":\"The content profile, a URI: `https://hcp.example/spec/profiles/general-context/2.0` or `https://hcp.example/spec/profiles/vc-evidence/2.0` in HCP 2.0-draft-3, or a custom profile (HCP A.3).\"},\"value\":{\"type\":[\"string\",\"object\"],\"description\":\"The statement, under the General Context profile: a string or a structured object (HCP 11.2).\"},\"language\":{\"type\":[\"string\",\"null\"],\"maxLength\":64,\"description\":\"The BCP 47 language tag of a string `value`, under the General Context profile (HCP 11.2). Optional; may be null.\"},\"evidence\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Under the VC Evidence profile, the index in `evidence` of the item whose credential is the content (HCP 4.2.2).\"}}},\"Uri\":{\"type\":\"string\",\"format\":\"uri\",\"minLength\":1,\"maxLength\":2048,\"pattern\":\"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+$\",\"description\":\"An absolute URI with no whitespace, as HCP writes every custom value at an extension point (HCP A.3).\"},\"Urn\":{\"type\":\"string\",\"pattern\":\"^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\",\"description\":\"An HCP identifier: a UUID in `urn:uuid:` form, of any UUID version (HCP 4.2), as HCP uses for entry, grant, directive and retrieval identifiers.\"},\"WriteRecord\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"HCP `record`, as a revision supplies it: provenance and relationships only (HCP 5.2.4). The provider assigns `status`, `version` and the rest.\",\"properties\":{\"provenance\":{\"$ref\":\"#/$defs/WriteProvenance\",\"description\":\"The provenance the client supplies (HCP 5.2.3).\"},\"relationships\":{\"type\":\"array\",\"maxItems\":256,\"items\":{\"$ref\":\"#/$defs/WriteRelationship\"},\"description\":\"Relationships to assert (HCP 4.2.3). The bound of 256 is a framework bound.\"}}},\"WriteRelationship\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"type\",\"target\"],\"description\":\"A relationship to assert (HCP 4.2.3, 5.2.3). Only a `contradicts` relationship may carry a `proposal` (HCP 4.7.4); not checked by the schema. The provider assigns `assertedBy` and `recordedAt` (HCP 5.2.3).\",\"properties\":{\"type\":{\"$ref\":\"#/$defs/RelationshipType\",\"description\":\"The kind of relationship.\"},\"target\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The related entry: its `ref` for a Context Client, its `id` for a Management Client (HCP 5.2.3).\"},\"proposal\":{\"$ref\":\"#/$defs/Proposal\",\"description\":\"A proposal for resolving the conflict, on a `contradicts` relationship only (HCP 4.7.4).\"}}},\"Proposal\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"act\",\"entry\",\"rationale\",\"weighed\"],\"description\":\"A proposal for resolving a conflict the client asserts, carried on a `contradicts` relationship (HCP 4.7.4). It changes nothing until the Context Subject acts. `proposedBy` and `proposedAt` are set by the provider, never taken from a request (HCP 4.7.4).\",\"properties\":{\"act\":{\"type\":\"string\",\"enum\":[\"reject\",\"accept\",\"supersede\"],\"description\":\"The act proposed (HCP 4.7.3).\"},\"entry\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The entry the act applies to: its `ref` for a Context Client, its `id` for a Management Client (HCP 5.2.3).\"},\"rationale\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":4096,\"description\":\"Why, in words the Context Subject can read (HCP 4.7.4).\"},\"weighed\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":64,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048},\"description\":\"What the proposal considered: an open set, of which HCP defines `basis`, `declarationType`, `standing`, `permittedPurposes`, `recency` and `confidence` (HCP 4.7.4).\"}}},\"WriteProvenance\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"HCP `record.provenance`, as a revision supplies it (HCP 5.2.4): the members are as for create, for the revised assertion, and the provider assigns every other provenance member (HCP 3.5). The create rules for `source` and `assertedBy.id` apply to the revised assertion (HCP 5.2.3, 5.2.4); they depend on the content and are not checked by the schema.\",\"properties\":{\"assertedBy\":{\"$ref\":\"#/$defs/AssertedBy\",\"description\":\"The Context Asserter.\"},\"assertedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the assertion was made. Omitted means the provider records `recordedAt` (HCP 5.2.3).\"},\"source\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The origin of the entry: a conversation or document identifier, `person-input` or `integration` (HCP 4.2, 5.2.3).\"}}},\"AssertedBy\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"id\"],\"description\":\"HCP `record.provenance.assertedBy`, as a request supplies it: the Context Asserter's identifier only. The provider assigns `assurance` (HCP 3.5, 5.2.3).\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The Context Asserter (HCP 3.2.6).\"}}},\"RevisionAssertion\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"The assertion members a revision may supply (HCP 5.2.4). `declarationType` omitted means unchanged. `confidence` is REQUIRED and non-null when the revised declaration type is `model-inferred`, and null or absent otherwise (HCP 4.2, 5.2.3); not checked by the schema, since the registry's Rust generator does not support `if`/`then`/`else`.\",\"properties\":{\"declarationType\":{\"type\":\"string\",\"enum\":[\"person-declared\",\"model-inferred\",\"issuer-attested\"],\"description\":\"The declaration type of the revised assertion (HCP 4.4). HCP's own values, carried verbatim.\"},\"confidence\":{\"type\":[\"string\",\"null\"],\"enum\":[\"high\",\"medium\",\"low\",null],\"description\":\"As for create (HCP 5.2.3).\"},\"validUntil\":{\"type\":[\"string\",\"null\"],\"format\":\"date-time\",\"description\":\"As for create: when the content stops holding (HCP 4.2).\"},\"basis\":{\"$ref\":\"#/$defs/Basis\",\"description\":\"As for create: what the assertion was drawn from (HCP 4.2.5).\"},\"permittedPurposes\":{\"type\":\"array\",\"maxItems\":256,\"uniqueItems\":true,\"items\":{\"$ref\":\"#/$defs/PurposeCode\"},\"description\":\"As for create: the purposes the asserter permits the entry to be used for (HCP 4.2.6). The bound of 256 is a framework bound.\"}}}}}"

// ResponsePayloadSchemaJSON is PayloadSchemaJSON for the success-response variant.
const ResponsePayloadSchemaJSON = "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$ref\":\"#/$defs/Response\",\"$defs\":{\"Response\":{\"$anchor\":\"response\",\"title\":\"HCP — Revise Entry — response payload\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"entry\"],\"description\":\"The HCP Revise result (HCP 5.2.4): the revised entry, with `record.version` (a disclosure's `version`) incremented by 1. Failures use trust-task-error, not this shape.\",\"properties\":{\"entry\":{\"anyOf\":[{\"$ref\":\"#/$defs/Disclosure\"},{\"$ref\":\"#/$defs/Entry\"}],\"description\":\"The revised entry: a Disclosure where the requester is a Context Client (HCP 7.4), otherwise the whole Entry. Its `id`, and its `ref` under the grant, are unchanged (HCP 5.2.4). HCP returns it as the result itself; this task wraps it in `entry`.\"}}},\"Entry\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"schema\",\"id\",\"type\",\"subject\",\"content\",\"assertion\",\"classification\",\"record\"],\"description\":\"An HCP entry, in the one form a provider emits (HCP 4.2, 4.3). A Context Client never receives one: it receives a Disclosure instead (HCP 7.4). The whole entry, with its stable `id`, reaches only the Context Subject's own access (HCP 7.4).\",\"properties\":{\"@context\":{\"type\":[\"array\",\"string\"],\"description\":\"The entry's JSON-LD context, `https://hcp.example/contexts/v2` in HCP 2.0-draft-3 (HCP 4.2).\"},\"schema\":{\"type\":\"string\",\"const\":\"https://hcp.example/spec/entry/2.0\",\"description\":\"The version of the entry structure, compared as an exact string (HCP 4.2, 1.7). HCP 2.0-draft-3 defines this one value.\"},\"id\":{\"$ref\":\"#/$defs/Urn\",\"description\":\"The entry's stable identifier, the same across all its versions (HCP 4.2). Never disclosed to a Context Client, which names the entry by a `ref` (HCP 7.4).\"},\"type\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":256},\"minItems\":1,\"description\":\"The entry's types. It MUST include `ContextEntry` (HCP 4.2). That rule is stated here and not in the schema: the registry's Rust generator does not support `contains`, so a validator does not check it.\"},\"subject\":{\"$ref\":\"#/$defs/EntrySubject\",\"description\":\"The Context Subject the entry is about.\"},\"content\":{\"$ref\":\"#/$defs/Content\",\"description\":\"What is said about the Context Subject, shaped by its content profile (HCP 4.2).\"},\"assertion\":{\"$ref\":\"#/$defs/Assertion\",\"description\":\"What the submitting client states about the assertion (HCP 4.2, 4.4).\"},\"classification\":{\"$ref\":\"#/$defs/Classification\",\"description\":\"HCP's classification of the entry: its categories, dimension and purpose limits (HCP 4.2, 4.5).\"},\"evidence\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/$defs/EvidenceItem\"},\"description\":\"Evidence items (HCP 4.2.2): at most one whose `role` is `content`. Absent or empty when the entry carries none. This rule is stated here and not in the schema: the registry's Rust generator does not support `contains`, so a validator does not check it.\"},\"record\":{\"$ref\":\"#/$defs/Record\",\"description\":\"The provider's record of the entry: status, version, provenance, relationships, conversion and metadata (HCP 4.2).\"}}},\"Record\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"status\",\"version\",\"provenance\"],\"description\":\"The provider's record of the entry (HCP 4.2). Withheld from a Context Client in full (HCP 7.4).\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"active\",\"deprecated\",\"conflicted\",\"expired\",\"revoked\",\"suspended\",\"deleted\"],\"description\":\"The entry's lifecycle state (HCP 4.2.4). HCP's own values, carried verbatim.\"},\"version\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The revision number: starts at 1 and increments by exactly 1 on each revision (HCP 4.2).\"},\"provenance\":{\"$ref\":\"#/$defs/Provenance\",\"description\":\"Who asserted, submitted, authorized, recorded and confirmed this version (HCP 3.5–3.8).\"},\"relationships\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/$defs/Relationship\"},\"description\":\"Relationships to other entries (HCP 4.2.3). Absent or empty when there are none.\"},\"conversion\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"from\",\"convertedAt\",\"convertedBy\"],\"description\":\"Present only on an entry converted from HCP v1 (HCP 4.3).\",\"properties\":{\"from\":{\"type\":\"string\",\"maxLength\":2048,\"description\":\"What the entry was converted from.\"},\"convertedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When it was converted.\"},\"convertedBy\":{\"type\":\"string\",\"maxLength\":2048,\"description\":\"Who converted it.\"},\"unmapped\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"v1 members the conversion did not map.\"}}},\"metadata\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"Free-form data the implementation attaches for its own purposes; carries no HCP meaning (HCP 4.2).\"}}},\"Relationship\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"type\",\"target\",\"assertedBy\",\"recordedAt\"],\"description\":\"A relationship from this entry to another (HCP 4.2.3). Only a `contradicts` relationship may carry a `proposal` (HCP 4.7.4), which is carried as HCP defines it. This rule is stated here and not as a schema conditional: the registry's Rust generator does not support `if`/`then`/`else`, so a validator does not check it.\",\"properties\":{\"type\":{\"$ref\":\"#/$defs/RelationshipType\",\"description\":\"The kind of relationship.\"},\"target\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The related entry's `id`.\"},\"assertedBy\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"role\",\"id\"],\"description\":\"Who asserted the relationship.\",\"properties\":{\"role\":{\"type\":\"string\",\"enum\":[\"management-client\",\"context-client\",\"authorization-service\",\"hcp-provider\"],\"description\":\"Their role (HCP 3.9). HCP's own values, carried verbatim.\"},\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"Their identifier.\"}}},\"recordedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the provider recorded the relationship.\"},\"proposal\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"A proposal for resolving a conflict, which changes nothing until the Context Subject acts (HCP 4.7.4).\"}}},\"Instant\":{\"type\":\"string\",\"format\":\"date-time\",\"description\":\"An RFC 3339 instant.\"},\"RelationshipType\":{\"type\":\"string\",\"enum\":[\"derivedFrom\",\"supersedes\",\"contradicts\",\"duplicates\"],\"description\":\"How one entry relates to another (HCP 4.2.3). HCP's own values, carried verbatim.\"},\"Provenance\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"assertedBy\",\"assertedAt\",\"source\",\"submittedByClient\",\"authorizedUnder\",\"recordedByProvider\",\"recordedAt\"],\"description\":\"The provenance of one version of an entry (HCP 4.2, 3.5).\",\"properties\":{\"assertedBy\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"id\",\"assurance\"],\"description\":\"The Context Asserter (HCP 3.5, 3.6).\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The Context Asserter's identifier.\"},\"assurance\":{\"$ref\":\"#/$defs/Assurance\",\"description\":\"How the asserter's identity was established.\"},\"via\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"kind\",\"id\"],\"description\":\"Present only where a client attested for an issuer under the issuer's authorization (HCP 3.7).\",\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"authorization-credential\",\"arrangement\"],\"description\":\"What the client attested under. HCP's own values, carried verbatim.\"},\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The identifier of the attestation authorization or the recorded arrangement.\"}}}}},\"assertedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the assertion was made, as the submitting client states it.\"},\"source\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The origin of the entry, as the submitting client states it: a conversation or document identifier, `person-input` or `integration` (HCP 4.2).\"},\"submittedByClient\":{\"$ref\":\"#/$defs/ClientDescription\",\"description\":\"The HCP Client that submitted this version, and its Client Operator (HCP 3.5).\"},\"authorizedUnder\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The grant under which this version was written.\"},\"recordedByProvider\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The HCP Provider that recorded this version.\"},\"recordedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the provider recorded this version.\"},\"confirmations\":{\"type\":\"array\",\"description\":\"Confirmation records for this version (HCP 3.8). Absent or empty when there are none.\",\"items\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"disposition\",\"confirmedBy\",\"confirmedAt\"],\"properties\":{\"disposition\":{\"type\":\"string\",\"enum\":[\"confirmed\",\"rejected\"],\"description\":\"Whether the Context Subject confirmed or rejected the version.\"},\"confirmedBy\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"id\"],\"description\":\"Who confirmed or rejected it.\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"Their identifier.\"}}},\"confirmedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When.\"}}}}}},\"ClientDescription\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"id\",\"name\",\"operator\"],\"description\":\"An HCP Client and its Client Operator, as recorded (HCP 3.5, 3.2.8).\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The client's identifier.\"},\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1024,\"description\":\"The client's name.\"},\"operator\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"id\",\"name\"],\"description\":\"The Client Operator.\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The operator's identifier.\"},\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1024,\"description\":\"The operator's name.\"}}}}},\"Assurance\":{\"type\":\"string\",\"enum\":[\"unverified\",\"authenticated\",\"cryptographically-verified\"],\"description\":\"How a Context Asserter's identity was established (HCP 3.6). HCP's own values, carried verbatim.\"},\"EvidenceItem\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"role\",\"type\"],\"description\":\"One evidence item (HCP 4.2.2). An item of a type the provider does not recognize is preserved and never raises assurance (HCP A.3). An item whose type is `verifiable-credential` MUST carry `credential`, an object with `@context`, `type`, `issuer` and `credentialSubject`, held whole as its issuer secured it (HCP 4.2.2). This rule is stated here and not as a schema conditional: the registry's Rust generator does not support `if`/`then`/`else`, so a validator does not check it.\",\"properties\":{\"role\":{\"type\":\"string\",\"enum\":[\"content\",\"supports\"],\"description\":\"`content`: the item's credential is the entry's content (VC Evidence profile). `supports`: the item backs content stated elsewhere in the entry (HCP 4.2.2).\"},\"type\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The evidence type: `verifiable-credential`, or a URI (HCP 4.2.2, A.3).\"},\"credential\":{\"description\":\"The credential: for `verifiable-credential`, a W3C Verifiable Credential with `@context`, `type`, `issuer` and `credentialSubject`, whose own data model governs its contents (HCP 4.2.2, 14.2).\"},\"verification\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"result\",\"at\"],\"description\":\"The provider's record of its most recent verification of the credential (HCP 4.2.2). Set only by the provider.\",\"properties\":{\"result\":{\"type\":\"string\",\"enum\":[\"verified\",\"failed\"],\"description\":\"The outcome.\"},\"at\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the provider verified.\"},\"by\":{\"type\":\"string\",\"enum\":[\"provider\",\"trust-domain\"],\"description\":\"Who verified: the provider, or the Context Subject's trust domain under end-to-end encrypted storage (HCP 4.8). HCP's own values, carried verbatim.\"}}}}},\"Classification\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"categories\"],\"description\":\"HCP's classification of the entry (HCP 4.2, 4.5). A grant reaches an entry when it covers any one of the entry's categories (HCP 4.5).\",\"properties\":{\"categories\":{\"type\":\"array\",\"minItems\":1,\"uniqueItems\":true,\"items\":{\"$ref\":\"#/$defs/Category\"},\"description\":\"One or more categories, without duplicates (HCP 4.2, 4.5). In a disclosure, only the categories the requesting grant covers (HCP 7.4).\"},\"dimension\":{\"type\":[\"string\",\"null\"],\"maxLength\":2048,\"description\":\"A free-form identifier of the dimension the entry addresses, scoped within its categories: a hint for conflict detection that grants and limits nothing (HCP 4.2).\"},\"permittedPurposes\":{\"type\":\"array\",\"uniqueItems\":true,\"items\":{\"$ref\":\"#/$defs/PurposeCode\"},\"description\":\"The Authorizing Principal's narrowing of the entry's purposes; absent means no limit (HCP 4.2.6).\"}}},\"PurposeCode\":{\"type\":\"string\",\"format\":\"uri\",\"minLength\":1,\"maxLength\":2048,\"pattern\":\"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+$\",\"description\":\"An HCP purpose code: an absolute URI naming the purpose for which context is requested or may be used (HCP 6.1.5.2).\"},\"Category\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"pattern\":\"^([a-z][a-z0-9_]*|[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+)$\",\"description\":\"An HCP context category (HCP 4.5), the primary unit of access control: either a slug from HCP's category registry, such as `general_preferences` or `health_context`, or a custom category written as an absolute URI under a domain its definer controls. A custom category is not portable between providers without bilateral agreement (HCP 4.5).\"},\"Assertion\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"declarationType\"],\"description\":\"What the submitting client states about the assertion (HCP 4.2). `confidence` is REQUIRED and non-null when `declarationType` is `model-inferred`, and null or absent otherwise (HCP 4.2, 4.4). This rule is stated here and not as a schema conditional: the registry's Rust generator does not support `if`/`then`/`else`, so a validator does not check it.\",\"properties\":{\"declarationType\":{\"type\":\"string\",\"enum\":[\"person-declared\",\"model-inferred\",\"issuer-attested\"],\"description\":\"What kind of party made the assertion (HCP 4.4); never omitted. HCP's own values, carried verbatim.\"},\"confidence\":{\"type\":[\"string\",\"null\"],\"enum\":[\"high\",\"medium\",\"low\",null],\"description\":\"How confident an inferring model is (HCP 4.2, 4.4).\"},\"validUntil\":{\"type\":[\"string\",\"null\"],\"format\":\"date-time\",\"description\":\"The instant after which the content no longer holds; absent or null means it does not expire (HCP 4.2). Not the instant after which a disclosed copy stops being usable, which is a disclosure's `useUntil` (HCP 7.6).\"},\"basis\":{\"$ref\":\"#/$defs/Basis\",\"description\":\"What the assertion was drawn from (HCP 4.2.5).\"},\"permittedPurposes\":{\"type\":\"array\",\"maxItems\":256,\"uniqueItems\":true,\"items\":{\"$ref\":\"#/$defs/PurposeCode\"},\"description\":\"The purposes the asserter permits the entry to be used for; absent means no limit (HCP 4.2.6). The bound of 256 is a framework bound, not an HCP requirement.\"}}},\"Basis\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"What an assertion was drawn from (HCP 4.2.5). It identifies no party but the Context Subject.\",\"properties\":{\"drawnFrom\":{\"type\":\"array\",\"maxItems\":256,\"items\":{\"type\":\"string\",\"maxLength\":2048},\"description\":\"The sources the assertion was drawn from. The bound of 256 is a framework bound, not an HCP requirement.\"},\"task\":{\"type\":\"string\",\"maxLength\":4096,\"description\":\"The task during which the assertion was made.\"},\"setting\":{\"type\":\"string\",\"maxLength\":4096,\"description\":\"The setting in which the assertion was made.\"},\"rationale\":{\"type\":\"string\",\"maxLength\":4096,\"description\":\"Why the asserter drew the conclusion.\"}}},\"Content\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"profile\"],\"description\":\"Entry content. `profile` names its shape (HCP 4.2). Under the General Context profile it carries `value` and optionally `language` (HCP 11.2); under the VC Evidence profile it carries `evidence`, the index of the evidence item holding the credential, and no `value` (HCP 4.2.2, 14). So `value` is REQUIRED under General Context, and under VC Evidence `evidence` is REQUIRED and `value` is forbidden. This rule is stated here and not as a schema conditional: the registry's Rust generator does not support `if`/`then`/`else`, so a validator does not check it.\",\"properties\":{\"profile\":{\"$ref\":\"#/$defs/Uri\",\"description\":\"The content profile, a URI: `https://hcp.example/spec/profiles/general-context/2.0` or `https://hcp.example/spec/profiles/vc-evidence/2.0` in HCP 2.0-draft-3, or a custom profile (HCP A.3).\"},\"value\":{\"type\":[\"string\",\"object\"],\"description\":\"The statement, under the General Context profile: a string or a structured object (HCP 11.2).\"},\"language\":{\"type\":[\"string\",\"null\"],\"maxLength\":64,\"description\":\"The BCP 47 language tag of a string `value`, under the General Context profile (HCP 11.2). Optional; may be null.\"},\"evidence\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Under the VC Evidence profile, the index in `evidence` of the item whose credential is the content (HCP 4.2.2).\"}}},\"Uri\":{\"type\":\"string\",\"format\":\"uri\",\"minLength\":1,\"maxLength\":2048,\"pattern\":\"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+$\",\"description\":\"An absolute URI with no whitespace, as HCP writes every custom value at an extension point (HCP A.3).\"},\"EntrySubject\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"id\"],\"description\":\"The subject of an entry (HCP 4.2).\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"A URI identifying the Context Subject of the HCP instance that holds the entry, possibly a pseudonym the provider issues (HCP 4.2).\"},\"relationship\":{\"type\":\"null\",\"description\":\"Reserved by HCP (HCP 4.2, 11.3); null where present.\"}}},\"Urn\":{\"type\":\"string\",\"pattern\":\"^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\",\"description\":\"An HCP identifier: a UUID in `urn:uuid:` form, of any UUID version (HCP 4.2), as HCP uses for entry, grant, directive and retrieval identifiers.\"},\"Disclosure\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"ref\",\"version\",\"content\",\"assertion\",\"classification\",\"standing\",\"useUntil\"],\"description\":\"A disclosed copy of an entry (HCP 7.4). It names the entry by a grant-scoped `ref`, never by its `id`, and withholds the entry's `id`, `subject`, `schema` and the whole of `record` (status, provenance, relationships, conversion, metadata): those members describe the person's activity with other systems, which no grant authorizes a client to learn (HCP 7.4). What the client needs to judge the entry it receives in `standing`.\",\"properties\":{\"ref\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"A reference to the entry, opaque to the client, stable for one grant and one entry and different under every other grant, and never derivable into the entry's `id` (HCP 7.4). The client names the entry by it in get entry, revise and withdraw; under any other grant it fails with not authorized.\"},\"version\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The entry version disclosed: the stored `record.version` (HCP 7.4, 4.2).\"},\"content\":{\"$ref\":\"#/$defs/Content\",\"description\":\"The content, as stored for the version disclosed (HCP 7.4).\"},\"evidence\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/$defs/DisclosedEvidenceItem\"},\"description\":\"The evidence, as stored (so at most one item whose `role` is `content`, HCP 4.2.2), including each item's `verification`, except that a credential may be disclosed in derived form (HCP 7.4, 14.9). Absent or empty when none is disclosed. The one-`content`-item rule is stated here and not in the schema: the registry's Rust generator does not support `contains`, so a validator does not check it.\"},\"assertion\":{\"$ref\":\"#/$defs/Assertion\",\"description\":\"The assertion, as stored for the version disclosed, including `basis` and `permittedPurposes` (HCP 7.4).\"},\"classification\":{\"$ref\":\"#/$defs/Classification\",\"description\":\"Only the entry's categories the requesting grant covers, with its dimension and its `permittedPurposes` where present; its other categories are withheld (HCP 7.4).\"},\"standing\":{\"$ref\":\"#/$defs/Standing\",\"description\":\"What the client needs to judge the entry's standing (HCP 7.4, 3.8).\"},\"useUntil\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"The instant after which the client MUST NOT use the copy, or pass it on, without fetching it again (HCP 7.6). The provider sets it at disclosure: the earliest explicit time that applies (such as `assertion.validUntil`), else a heuristic of at least 1 hour; never more than 30 days after disclosure, 24 hours for an entry of High default sensitivity, or 1 hour where the client has no registered notification endpoint (HCP 7.6).\"},\"onwardSharing\":{\"const\":true,\"description\":\"Present, and true, only where the client may share from this entry under HCP 3.12: the detail of the grant that reaches the entry carries `onwardSharing` and every category of the entry has a default sensitivity of Low. Omitted otherwise (HCP 7.4).\"},\"relationships\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/$defs/DisclosedRelationship\"},\"description\":\"Only the relationships whose target is disclosed in the same response, with the target named by its `ref` (HCP 7.4, 4.2.3).\"},\"provenance\":{\"$ref\":\"#/$defs/DisclosedProvenance\",\"description\":\"Present only where the requesting grant includes the `provenance` action for a category of the entry (HCP 7.4.1).\"}},\"not\":{\"anyOf\":[{\"required\":[\"id\"]},{\"required\":[\"subject\"]},{\"required\":[\"record\"]},{\"required\":[\"schema\"]}]}},\"DisclosedProvenance\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"submittedBy\",\"source\",\"assertedAt\",\"recordedAt\"],\"description\":\"Provenance on request (HCP 7.4.1): names, never identifiers. It MUST NOT carry an identifier of a client, a Client Operator, a grant, a conversation or a document, nor `confirmedBy`.\",\"properties\":{\"submittedBy\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"name\",\"operator\"],\"description\":\"The names of the client that submitted the version disclosed and of its Client Operator.\",\"properties\":{\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1024,\"description\":\"The client's name.\"},\"operator\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1024,\"description\":\"The Client Operator's name.\"}}},\"source\":{\"type\":\"string\",\"enum\":[\"conversation\",\"document\",\"person-input\",\"integration\"],\"description\":\"The kind of origin the stored `source` records, not its value (HCP 7.4.1). HCP's own values, carried verbatim.\"},\"assertedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the assertion was made.\"},\"recordedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the provider recorded the version.\"}},\"not\":{\"anyOf\":[{\"required\":[\"id\"]},{\"required\":[\"confirmedBy\"]},{\"required\":[\"authorizedUnder\"]},{\"required\":[\"submittedByClient\"]}]}},\"DisclosedRelationship\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"type\",\"target\"],\"description\":\"A relationship as disclosed (HCP 7.4).\",\"properties\":{\"type\":{\"$ref\":\"#/$defs/RelationshipType\",\"description\":\"The kind of relationship.\"},\"target\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The `ref` of the related entry, disclosed in the same response.\"}}},\"Standing\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"assurance\",\"confirmed\"],\"description\":\"The standing of the disclosed version (HCP 7.4).\",\"properties\":{\"assurance\":{\"$ref\":\"#/$defs/Assurance\",\"description\":\"The stored `record.provenance.assertedBy.assurance`.\"},\"confirmed\":{\"type\":\"boolean\",\"description\":\"True where the most recent confirmation record on the version disclosed is `confirmed` (HCP 7.4, 3.8).\"}}},\"DisclosedEvidenceItem\":{\"description\":\"An evidence item as disclosed (HCP 7.4). An item carrying a derived credential adds `revealed`.\",\"allOf\":[{\"$ref\":\"#/$defs/EvidenceItem\"}],\"properties\":{\"revealed\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"maxLength\":2048},\"description\":\"The JSON Pointers into the stored credential of the claims a derived credential reveals (HCP 7.4, 14.9).\"}}}}}"

// Spec is the SPEC §7.2 policy for the request variant, taken from this
// specification's front matter. Pass it to trusttasks.ConsumeInbound — items 5b,
// 7 and 8 are per-specification and cannot be derived from the document alone,
// and item 2 needs the schema it carries.
var Spec = trusttasks.SpecPolicy{
	TypeURI:             TypeURI,
	IsBearer:            false,
	IsProofRequired:     true,
	IsRecipientRequired: true,
	IsIssuedAtRequired:  true,
	PayloadSchema:       PayloadSchemaJSON,
	MaxDocumentBytes:    524288,
}

// ResponseSpec is the SPEC §7.2 policy for the success-response variant.
// IsRecipientRequired tracks the *issuer* party's requirement, because a response
// swaps the parties (§7.3 item 5).
var ResponseSpec = trusttasks.SpecPolicy{
	TypeURI:             ResponseTypeURI,
	IsBearer:            false,
	IsProofRequired:     true,
	IsRecipientRequired: true,
	IsIssuedAtRequired:  true,
	PayloadSchema:       ResponsePayloadSchemaJSON,
	MaxDocumentBytes:    524288,
}
